using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.WebUtilities;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
namespace Society.Api;
public static class CommunicationWebhookEndpoints {
 public static void Map(RouteGroupBuilder api){
 api.MapGet("/communications/webhooks/{id:guid}",async(Guid id,HttpRequest request,AppDb db,CommunicationProviders providers)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(a=>a.Id==id)??throw new AccessDeniedException();var secret=providers.Secrets(account)["verifyToken"]?.ToString()??"";if(account.Provider!="Meta"||secret.Length<16||request.Query["hub.mode"]!="subscribe"||!CommunicationProviders.Fixed(secret,request.Query["hub.verify_token"].ToString()))throw new AccessDeniedException();return Results.Text(request.Query["hub.challenge"].ToString());}).RequireRateLimiting("community");
 api.MapPost("/communications/webhooks/{id:guid}",async(Guid id,HttpRequest request,AppDb db,CommunicationProviders providers,IConfiguration config)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(a=>a.Id==id)??throw new AccessDeniedException();var secrets=providers.Secrets(account);using var buffer=new MemoryStream();var bytes=new byte[8192];int read;while((read=await request.Body.ReadAsync(bytes))>0){if(buffer.Length+read>1048576)throw new DomainException("Webhook exceeds 1 MB");buffer.Write(bytes,0,read);}var raw=Encoding.UTF8.GetString(buffer.ToArray());var signed=false;var updates=new List<(string key,string providerId,string status,string? from,string? body,string? subject)>();
 if(account.Provider=="Meta"){var supplied=request.Headers["X-Hub-Signature-256"].ToString();var expected="sha256="+Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(secrets["appSecret"]?.ToString()??""),buffer.ToArray())).ToLowerInvariant();signed=secrets["appSecret"]?.ToString().Length>=16&&CommunicationProviders.Fixed(supplied,expected);if(signed){var root=JsonNode.Parse(raw);foreach(var entry in root?["entry"]?.AsArray()??[]){foreach(var change in entry?["changes"]?.AsArray()??[]){var value=change?["value"];if(value?["metadata"]?["phone_number_id"]?.ToString()!=account.ProviderReference)throw new AccessDeniedException();foreach(var status in value?["statuses"]?.AsArray()??[])updates.Add((status!["id"]+":"+status["status"]+":"+status["timestamp"],status["id"]!.ToString(),Normalize(status["status"]!.ToString()),null,null,null));foreach(var message in value?["messages"]?.AsArray()??[])updates.Add((message!["id"]!.ToString(),message["id"]!.ToString(),"Incoming",message["from"]?.ToString(),message["text"]?["body"]?.ToString()??"[Unsupported incoming media]",null));}}}}
 else if(account.Provider=="Twilio"){var form=QueryHelpers.ParseQuery(raw);var url=(config["Communications:WebhookBaseUrl"]??config["PublicUrl"]??"").TrimEnd('/')+request.Path+request.QueryString;var text=url+string.Concat(form.OrderBy(p=>p.Key,StringComparer.Ordinal).Select(p=>p.Key+p.Value.ToString()));var signature=Convert.ToBase64String(HMACSHA1.HashData(Encoding.UTF8.GetBytes(secrets["token"]?.ToString()??""),Encoding.UTF8.GetBytes(text)));signed=CommunicationProviders.Fixed(signature,request.Headers["X-Twilio-Signature"].ToString())&&form.GetValueOrDefault("AccountSid").ToString()==account.ProviderReference;if(signed){var sid=form.GetValueOrDefault("MessageSid").ToString();var status=form.GetValueOrDefault("MessageStatus").ToString();if(form.ContainsKey("Body")){if(form.GetValueOrDefault("To").ToString()!=account.Sender)throw new AccessDeniedException();updates.Add((sid,sid,"Incoming",form.GetValueOrDefault("From").ToString(),form.GetValueOrDefault("Body").ToString(),null));}else updates.Add((sid+":"+status,sid,Normalize(status),null,null,null));}}
 else if(account.Provider=="Resend"){var stamp=request.Headers["svix-timestamp"].ToString();var eventId=request.Headers["svix-id"].ToString();if(long.TryParse(stamp,out var seconds)&&Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeSeconds()-seconds)<300){try{var key=Convert.FromBase64String((secrets["webhookSecret"]?.ToString()??"").Replace("whsec_",""));var expected=Convert.ToBase64String(HMACSHA256.HashData(key,Encoding.UTF8.GetBytes(eventId+"."+stamp+"."+raw)));signed=request.Headers["svix-signature"].ToString().Split(' ').Any(s=>s.StartsWith("v1,")&&CommunicationProviders.Fixed(s[3..],expected));}catch{signed=false;}}if(signed){var body=JsonNode.Parse(raw)!;var emailId=body["data"]?["email_id"]?.ToString()??"";if(body["type"]?.ToString()=="email.received"&&account.InboundEnabled){using var client=providers.Client();using var fetch=new HttpRequestMessage(HttpMethod.Get,"https://api.resend.com/emails/receiving/"+Uri.EscapeDataString(emailId));fetch.Headers.Authorization=new("Bearer",secrets["token"]?.ToString());using var response=await client.SendAsync(fetch);response.EnsureSuccessStatusCode();var received=JsonNode.Parse(await response.Content.ReadAsStringAsync())!;if(received["to"]?.AsArray().Any(to=>string.Equals(to?.ToString(),account.Sender,StringComparison.OrdinalIgnoreCase))!=true)throw new AccessDeniedException();var from=received["from"]?.ToString()??"";if(!System.Net.Mail.MailAddress.TryCreate(from,out var address))throw new DomainException("Provider returned an invalid sender");updates.Add((eventId,emailId,"Incoming",address.Address,received["text"]?.ToString()??"[HTML-only incoming email; plain-text body unavailable]",received["subject"]?.ToString()));}else updates.Add((eventId,emailId,Normalize(body["type"]?.ToString()??""),null,null,null));}}
 else if(account.Provider is "Gateway" or "Test"){if(account.Provider=="Test"&&!providers.MockAllowed)throw new AccessDeniedException();var stamp=request.Headers["X-Communication-Timestamp"].ToString();var expected=Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(secrets["webhookSecret"]?.ToString()??""),Encoding.UTF8.GetBytes(stamp+"."+raw))).ToLowerInvariant();signed=long.TryParse(stamp,out var seconds)&&Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeSeconds()-seconds)<300&&secrets["webhookSecret"]?.ToString().Length>=16&&CommunicationProviders.Fixed(expected,request.Headers["X-Communication-Signature"].ToString());if(signed){var body=JsonNode.Parse(raw)!;updates.Add((body["id"]!.ToString(),body["providerId"]?.ToString()??"",Normalize(body["status"]?.ToString()??""),body["from"]?.ToString(),body["body"]?.ToString(),body["subject"]?.ToString()));}}
 if(!signed)throw new AccessDeniedException();await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,account.TenantId);var processed=0;foreach(var update in updates){if(update.key.Length is <1 or >300)throw new DomainException("Invalid provider event identifier");if(await db.Set<ProviderEvent>().AnyAsync(e=>e.AccountId==id&&e.ExternalId==update.key))continue;db.Add(new ProviderEvent{TenantId=account.TenantId,AccountId=id,ExternalId=update.key,ProviderId=update.providerId,Kind=update.status,PayloadHash=CommunityService.Hash(raw)});if(update.status=="Incoming"&&account.InboundEnabled&&update.from!=null&&update.body!=null){var address=update.from.StartsWith('+')?update.from:account.Channel=="WhatsApp"?"+"+update.from:update.from;var conversation=await db.Set<Conversation>().Where(c=>c.TenantId==account.TenantId&&c.AccountId==id&&c.Kind=="Team"&&c.ExternalAddress==address).OrderByDescending(c=>c.LastAt).FirstOrDefaultAsync();if(conversation==null){conversation=new(){TenantId=account.TenantId,OwnerId=Guid.Empty,UnitId=account.UnitId,Kind="Team",Channel=account.Channel,AccountId=id,ExternalAddress=address,Subject=update.subject??"Incoming "+account.Channel+" inquiry",DirectKey="external:"+id+":"+CommunityService.Hash(address)};db.Add(conversation);}db.Add(new CommunicationMessage{TenantId=account.TenantId,ConversationId=conversation.Id,SenderId=Guid.Empty,Direction="Incoming",Body=update.body.Length>12000?update.body[..12000]:update.body,Status="Received",ClientKey=update.providerId});conversation.LastAt=DateTimeOffset.UtcNow;if(new[]{"STOP","UNSUBSCRIBE","CANCEL"}.Contains(update.body.Trim().ToUpperInvariant()))await Suppress(db,account.TenantId,account.Channel,address,"Provider opt-out");}
 else{var job=await db.Outbox.SingleOrDefaultAsync(o=>o.TenantId==account.TenantId&&o.AccountId==id&&o.ProviderId==update.providerId);if(job!=null){if(update.status=="Delivered"){job.DeliveredAt??=DateTimeOffset.UtcNow;if(job.ReadAt==null)job.Status="Delivered";}else if(update.status=="Read"){job.DeliveredAt??=DateTimeOffset.UtcNow;job.ReadAt=DateTimeOffset.UtcNow;job.Status="Read";}else if(update.status is "Failed" or "Bounced" or "Complaint"){job.Status=update.status;job.Error="Verified provider "+update.status;if(update.status is "Bounced" or "Complaint")await Suppress(db,account.TenantId,job.Channel,job.Recipient,update.status);}if(job.MessageId!=null){var message=await db.Set<CommunicationMessage>().FindAsync(job.MessageId);if(message!=null)message.Status=job.Status;}}}processed++;}await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{processed});}).RequireRateLimiting("community");
 api.MapPost("/communications/unsubscribe",async(ReactionWrite r,AppDb db)=>{var hash=CommunityService.Hash(r.Kind);var job=await db.Outbox.AsNoTracking().SingleOrDefaultAsync(o=>o.UnsubscribeHash==hash&&o.TenantId!=null)??throw new DomainException("Invalid unsubscribe reference");await Suppress(db,job.TenantId!.Value,job.Channel,job.Recipient,"Recipient unsubscribe");await db.SaveChangesAsync();return Results.Ok(new{message="Future messages on this channel are suppressed for this society."});}).RequireRateLimiting("community");
 }
 static string Normalize(string status)=>status.ToLowerInvariant() switch{"sent" or "accepted" or "email.sent"=>"Accepted","delivered" or "email.delivered"=>"Delivered","read"=>"Read","failed" or "undelivered" or "email.failed"=>"Failed","bounced" or "email.bounced"=>"Bounced","complained" or "email.complained"=>"Complaint","incoming"=>"Incoming",_=>"Observed"};
 public static async Task Suppress(AppDb db,Guid tenant,string channel,string address,string reason){var hash=CommunityService.Hash(address.ToLowerInvariant());if(!await db.Set<CommunicationSuppression>().AnyAsync(s=>s.TenantId==tenant&&s.Channel==channel&&s.DestinationHash==hash))db.Add(new CommunicationSuppression{TenantId=tenant,Channel=channel,DestinationHash=hash,Reason=reason});}
}
